import{_ as i,o as a,c as e,a2 as o}from"./chunks/framework.CBWbbCW8.js";const p=JSON.parse('{"title":"账户问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"account/troubleshooting.md","filePath":"account/troubleshooting.md","lastUpdated":1784973959000}'),t={name:"account/troubleshooting.md"};function r(n,l,h,d,s,c){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="账户问题排查" tabindex="-1">账户问题排查 <a class="header-anchor" href="#账户问题排查" aria-label="Permalink to &quot;账户问题排查&quot;">​</a></h1><p>这一页整理充值、余额、订阅和发票相关的常见问题。</p><h2 id="在线充值不可用" tabindex="-1">在线充值不可用 <a class="header-anchor" href="#在线充值不可用" aria-label="Permalink to &quot;在线充值不可用&quot;">​</a></h2><p>页面可能提示“尚未启用在线充值”。处理方式：</p><ul><li>使用兑换码。</li><li>联系管理员确认充值入口是否开放。</li><li>等待平台恢复支付渠道。</li></ul><h2 id="支付成功但余额没变" tabindex="-1">支付成功但余额没变 <a class="header-anchor" href="#支付成功但余额没变" aria-label="Permalink to &quot;支付成功但余额没变&quot;">​</a></h2><p>按顺序检查：</p><ol><li>刷新 <code>Wallet</code> 页面。</li><li>查看是否有新钱包流水。</li><li>查看订单状态是否成功。</li><li>核对支付账号是否和当前登录账号一致。</li><li>保存订单号、支付截图、支付时间后联系平台。</li></ol><h2 id="订阅购买失败" tabindex="-1">订阅购买失败 <a class="header-anchor" href="#订阅购买失败" aria-label="Permalink to &quot;订阅购买失败&quot;">​</a></h2><p>常见原因：</p><ul><li>余额不足。</li><li>套餐已下架或暂未开放。</li><li>优惠码不可用。</li><li>支付方式不可用。</li><li>当前账号没有购买权限。</li></ul><p>处理方式：</p><ol><li>先确认钱包余额。</li><li>换一个套餐或支付方式。</li><li>不使用优惠码重试。</li><li>联系平台确认订阅功能是否对当前账号开放。</li></ol><h2 id="看不到订阅套餐" tabindex="-1">看不到订阅套餐 <a class="header-anchor" href="#看不到订阅套餐" aria-label="Permalink to &quot;看不到订阅套餐&quot;">​</a></h2><p>可能原因：</p><ul><li>当前没有可购买套餐。</li><li>账号未登录或登录状态失效。</li><li>订阅模块未对当前用户开放。</li><li>页面数据加载失败。</li></ul><p>建议刷新页面，重新登录后再试。如果仍然看不到，以平台控制台显示为准。</p><h2 id="余额消耗过快" tabindex="-1">余额消耗过快 <a class="header-anchor" href="#余额消耗过快" aria-label="Permalink to &quot;余额消耗过快&quot;">​</a></h2><p>排查方向：</p><ul><li>到 <code>Usage Logs</code> 查看消耗最高的模型。</li><li>检查是否使用了高倍率模型。</li><li>检查是否有代码工具持续调用。</li><li>给测试 API Key 设置额度限制。</li><li>减少长上下文请求和最大输出长度。</li></ul><h2 id="发票无法申请" tabindex="-1">发票无法申请 <a class="header-anchor" href="#发票无法申请" aria-label="Permalink to &quot;发票无法申请&quot;">​</a></h2><p>可能原因：</p><ul><li>订单未支付成功。</li><li>当前订单不支持开票。</li><li>发票中心未开放。</li><li>发票信息不完整。</li></ul><p>处理方式是先确认订单状态，再联系平台处理。</p>',24)])])}const _=i(t,[["render",r]]);export{p as __pageData,_ as default};
